import re


_JOB_PATTERN = re.compile(
    r"JOB\s+(?P<name>\S+)\s+"
    r"AT\s+(?P<at>\d{2}:\d{2})\s+"
    r"RUN\s+(?P<script>\S+)"
    r"(?:\s+ON_ERROR\s+(?P<on_error>ABORT|CONTINUE|RETRY:\d+))?"
)


def parse_schedule(cfg_text: str) -> list[dict]:
    schedule: list[dict] = []

    for line_number, raw_line in enumerate(cfg_text.splitlines(), start=1):
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue

        match = _JOB_PATTERN.fullmatch(line)
        if match is None:
            raise ValueError(f"Invalid schedule line {line_number}: {raw_line!r}")

        at = match.group("at")
        hour, minute = (int(part) for part in at.split(":"))
        if hour > 23 or minute > 59:
            raise ValueError(f"Invalid time on line {line_number}: {at!r}")

        clause = match.group("on_error")
        if clause is None or clause == "ABORT":
            on_error = {"policy": "ABORT", "retries": 0}
        elif clause == "CONTINUE":
            on_error = {"policy": "CONTINUE", "retries": 0}
        else:
            on_error = {
                "policy": "RETRY",
                "retries": int(clause.removeprefix("RETRY:")),
            }

        schedule.append(
            {
                "name": match.group("name"),
                "at": at,
                "script": match.group("script"),
                "on_error": on_error,
            }
        )

    return schedule
